// Fun Gradient Pallet Generator
vec3 pal(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.263, 0.416, 0.557);

    return a + b*cos(6.28318*(c*t+d));
}

// Rotation matrix function
mat2 rotate(float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return mat2(c, -s, s, c);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //NORMALIZE UV from -1 to 1 
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;


    // Get time as T.
    float t = iTime * .5;
    float sinT = sin(t);

    // Final Color
    vec3 finCol = vec3(0.,0.,0.);

    // -------------------------//
    //         MOD VALS         //
    // -------------------------//
    float tileCount = .99;

    // -------------------------//
    //      NORMALIZE MODS      //
    // -------------------------//
    tileCount *= 5.;


    // -------------------------//
    //         DO CODE          //
    // -------------------------//

    // Apply rotation to UV coordinates
    uv = rotate(t) * uv;

    // Repeat UV by creating tiles
    vec2 tileCountV = vec2(tileCount*(sin(t)+1.05), tileCount*(sin(t)+1.05)); // Number of tiles in x and y
    vec2 uvTile = fract(uv * tileCountV) - 0.5; // Wrap UV into 0.0 to 1.0, then center at 0.0

    //Create particle
    float d = length(uvTile);
    d = smoothstep(d, .3, .35);

    // Final color pulls from pallete, and modulates with sin. Once calculated, mulitple by d to create brightness map.
    finCol = pal(sin((sin(10.32 * t) + 20.) * uv.x * uv.y * d)) * d;

    //fragColor = vec4(d,d,d, 1.0);

    fragColor = vec4(finCol, 1.0);
}
